**numbers.go**

```go
package lesson

func normalise(value int) int {
	if value < 0 {
		return 0
	}
	return value
}

func Add(a, b int) int {
	return normalise(a) + normalise(b)
}
```

**numbers_internal_test.go**

```go
package lesson

import "testing"

func TestNormalise(t *testing.T) {
	if got := normalise(-2); got != 0 {
		t.Fatalf("normalise(-2) = %d; want 0", got)
	}
}
```

**numbers_external_test.go**

```go
package lesson_test

import (
	"testing"

	lesson "example.test/lesson"
)

func TestAddPublicAPI(t *testing.T) {
	if got := lesson.Add(-2, 5); got != 5 {
		t.Fatalf("Add(-2, 5) = %d; want 5", got)
	}
}
```

**Run it**

```bash
go test ./...
```

The external test can import only `Add`; the internal test can inspect the private normalisation rule without changing the exported API.

**app.go**

```go
package lesson

import (
	"fmt"
	"net/http"
	"strings"
)

func Slug(value string) string {
	return strings.ToLower(strings.ReplaceAll(strings.TrimSpace(value), " ", "-"))
}

func Handler(w http.ResponseWriter, r *http.Request) {
	fmt.Fprint(w, Slug(r.URL.Query().Get("title")))
}
```

**app_test.go**

```go
package lesson

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestSlug(t *testing.T) {
	if got := Slug(" Go Tests "); got != "go-tests" {
		t.Fatalf("Slug = %q; want go-tests", got)
	}
}

func TestHandlerIntegration(t *testing.T) {
	request := httptest.NewRequest(http.MethodGet, "/?title=Go+Tests", nil)
	recorder := httptest.NewRecorder()
	Handler(recorder, request)
	response := recorder.Result()
	defer response.Body.Close()
	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	if string(body) != "go-tests" {
		t.Fatalf("body = %q; want go-tests", body)
	}
}

func ExampleSlug() {
	fmt.Println(Slug("Go Tests"))
	// Output: go-tests
}
```

**Run it**

```bash
go test ./...
```

All three use the same toolchain, but each retains a different boundary and therefore provides a different kind of confidence.

**reverse.go**

```go
package lesson

func Reverse(value string) string {
	runes := []rune(value)
	for left, right := 0, len(runes)-1; left < right; left, right = left+1, right-1 {
		runes[left], runes[right] = runes[right], runes[left]
	}
	return string(runes)
}
```

**reverse_test.go**

```go
package lesson

import (
	"testing"
	"unicode/utf8"
)

func TestReverse(t *testing.T) {
	if got := Reverse("Go語"); got != "語oG" {
		t.Fatalf("Reverse = %q; want 語oG", got)
	}
}

func BenchmarkReverse(b *testing.B) {
	for b.Loop() {
		_ = Reverse("interview preparation")
	}
}

func FuzzReverseTwice(f *testing.F) {
	for _, seed := range []string{"", "Go", "語🙂"} {
		f.Add(seed)
	}
	f.Fuzz(func(t *testing.T, value string) {
		if !utf8.ValidString(value) {
			t.Skip()
		}
		if got := Reverse(Reverse(value)); got != value {
			t.Fatalf("double reverse = %q; want %q", got, value)
		}
	})
}
```

**Run it**

```bash
go test ./...
go test -bench '^BenchmarkReverse$' -run '^$' -benchtime=1x ./...
go test -run '^FuzzReverseTwice$' ./...
```

The ordinary command runs the fixed test and fuzz seeds. The benchmark command measures one iteration for a quick validated example; real measurement should run long enough to stabilise.
